-- STEP 20 (APPLIED 2026-10-18): KNUST masters programmes (218 rows, all unverified). Source: data/ghana-public-universities/knust_masters.csv
-- Skips any programme already present. Run as one statement. '@G' and '@B' stand for the two repeated entry notes.
insert into public.programs (school_id, name, level, field, min_degree_class, entry_note, verified)
select s.id, v.name, 'Masters', v.field, v.cls,
  case v.note when '@G' then 'KNUST rule for all masters: a bachelor''s degree or equivalent in the relevant field, with preference to First or Second Class holders. No programme-specific class is printed for this programme.' when '@B' then 'KNUST School of Business page: bachelor''s with at least Second Class Lower in a relevant field; work experience preferred; interview.' else nullif(v.note, '') end, false
from public.schools s
cross join (values
